export function multiPathVerifier(paths) {
  const results = paths.map(path => path.run());
  const inconsistencies = [];

  for (let i = 0; i < results.length - 1; i++) {
    for (let j = i + 1; j < results.length; j++) {
      if (JSON.stringify(results[i]) !== JSON.stringify(results[j])) {
        inconsistencies.push({ pathA: paths[i].name, pathB: paths[j].name });
      }
    }
  }

  return { results, inconsistencies };
}